class Solution {
public:
    string addBoldTag(string s, vector<string>& words) {
        int n = s.size();
        vector<bool> bold(n, false);

        for (const string& w : words) {
            size_t start = s.find(w);
            while (start != string::npos) {
                for (size_t i = start; i < start + w.size(); i++) bold[i] = true;
                start = s.find(w, start + 1);
            }
        }

        string res = "";
        for (int i = 0; i < n; i++) {
            if (bold[i] && (i == 0 || !bold[i - 1])) res += "<b>";
            res.push_back(s[i]);
            if (bold[i] && (i == n - 1 || !bold[i + 1])) res += "</b>";
        }
        return res;
    }
};

class Solution {
    public String addBoldTag(String s, String[] words) {
        int n = s.length();
        boolean[] bold = new boolean[n];

        for (String w : words) {
            int start = s.indexOf(w);
            while (start != -1) {
                for (int i = start; i < start + w.length(); i++) bold[i] = true;
                start = s.indexOf(w, start + 1);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (bold[i] && (i == 0 || !bold[i - 1])) sb.append("<b>");
            sb.append(s.charAt(i));
            if (bold[i] && (i == n - 1 || !bold[i + 1])) sb.append("</b>");
        }
        return sb.toString();
    }
}

var addBoldTag = function(s, words) {
    const n = s.length;
    const bold = new Array(n).fill(false);

    for (const w of words) {
        let start = s.indexOf(w);
        while (start !== -1) {
            for (let i = start; i < start + w.length; i++) bold[i] = true;
            start = s.indexOf(w, start + 1);
        }
    }

    let res = "";
    for (let i = 0; i < n; i++) {
        if (bold[i] && (i === 0 || !bold[i - 1])) res += "<b>";
        res += s[i];
        if (bold[i] && (i === n - 1 || !bold[i + 1])) res += "</b>";
    }
    return res;
